namespace Instancium.Publisher.Tui.Components;

using Spectre.Console;
using Spectre.Console.Rendering;
using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Text.RegularExpressions;

/// <summary>
/// Transforms raw Markdown release notes generated by the LLM into native Spectre.Console renderables.
/// Addresses AST boundary mismatches where AI outputs multi-line blockquotes without continuous leading tokens.
/// </summary>
public static partial class MarkdownReleaseNotesRenderer
{
    [GeneratedRegex(@"\`(.*?)\`", RegexOptions.Compiled)]
    private static partial Regex InlineCodeRegex();

    /// <summary>
    /// Parses Markdown release notes into structured console renderables.
    /// Safely isolates Executive Summary text from table definitions and normalizes console markup tags.
    /// </summary>
    /// <param name="markdown">Raw Markdown text stream emitted by the inference pipeline.</param>
    /// <returns>A consolidated Spectre.Console renderable block.</returns>
    public static IRenderable Render(string markdown)
    {
        if (string.IsNullOrWhiteSpace(markdown))
        {
            return new Text(string.Empty);
        }

        var lines = markdown.Split(['\r', '\n'], StringSplitOptions.None);
        var summaryBuilder = new StringBuilder();
        Table? table = null;
        bool inSummaryBlock = false;

        foreach (string rawLine in lines)
        {
            string line = rawLine.Trim();

            if (string.IsNullOrWhiteSpace(line))
            {
                if (inSummaryBlock && summaryBuilder.Length > 0)
                {
                    inSummaryBlock = false;
                }
                continue;
            }

            if (line.StartsWith('|'))
            {
                inSummaryBlock = false;
                ProcessTableRow(line, ref table);
                continue;
            }

            if (line.StartsWith('>') || inSummaryBlock)
            {
                inSummaryBlock = true;
                string sanitizedLine = ExtractSummaryContent(line);
                if (!string.IsNullOrWhiteSpace(sanitizedLine))
                {
                    summaryBuilder.AppendLine(sanitizedLine);
                }
            }
        }

        return ComposeLayout(summaryBuilder.ToString().Trim(), table, markdown);
    }

    private static string ExtractSummaryContent(string rawLine)
    {
        string stripped = rawLine.StartsWith('>') ? rawLine.TrimStart('>', ' ').Trim() : rawLine;

        return stripped
            .Replace("**Executive Summary**", string.Empty, StringComparison.OrdinalIgnoreCase)
            .Replace("Executive Summary", string.Empty, StringComparison.OrdinalIgnoreCase)
            .Trim();
    }

    private static void ProcessTableRow(string line, ref Table? table)
    {
        var cells = line.Split('|', StringSplitOptions.RemoveEmptyEntries)
            .Select(c => c.Trim())
            .ToArray();

        if (cells.Length == 0)
        {
            return;
        }

        if (cells[0].Contains("---") || (cells.Length > 1 && cells[1].Contains("---")))
        {
            return;
        }

        if (table == null)
        {
            table = new Table().Expand().Border(TableBorder.Rounded).BorderColor(Color.Grey);
            foreach (string header in cells)
            {
                table.AddColumn($"[bold silver]{Markup.Escape(header)}[/]");
            }
        }
        else if (cells.Length == table.Columns.Count)
        {
            string[] formattedCells = cells.Select(c =>
            {
                string escaped = Markup.Escape(c);
                return InlineCodeRegex().Replace(escaped, "[cyan]$1[/]");
            }).ToArray();

            table.AddRow(formattedCells);
        }
    }

    private static IRenderable ComposeLayout(string summaryText, Table? table, string fallbackRawMarkdown)
    {
        var elements = new List<IRenderable>();

        if (!string.IsNullOrEmpty(summaryText))
        {
            var summaryPanel = new Panel($"[silver]{Markup.Escape(summaryText)}[/]")
                .Header("[bold green]Release Impact: Executive Summary[/]")
                .BorderColor(Color.Green)
                .RoundedBorder()
                .Expand();

            elements.Add(summaryPanel);
            elements.Add(new Text(string.Empty));
        }

        if (table != null)
        {
            elements.Add(table);
        }

        if (elements.Count == 0)
        {
            return new Markup($"[silver]{Markup.Escape(fallbackRawMarkdown)}[/]");
        }

        return new Rows(elements);
    }
}